        $h = Invoke-RestMethod -Uri "http://localhost:8080/actuator/health" -TimeoutSec 3
        if ($h.status -eq "UP") { $ok = $true; break }
    } catch {}
}
Write-Output "health up: $ok"
if ($ok) {
    $body = '{"cues":[{"seq":1,"cueType":"LIGHT","triggerPhrase":"kai-mu","durationSeconds":30},{"seq":2,"cueType":"SOUND","triggerPhrase":"thunder","durationSeconds":5}]}'
    $v = Invoke-RestMethod -Method Post -Uri "http://localhost:8080/api/cue-versions" -ContentType "application/json" -Body $body
    Write-Output "versionId=$($v.versionId)"
    $f = Invoke-RestMethod -Method Post -Uri "http://localhost:8080/api/cue-versions/$($v.versionId)/freeze"
    Write-Output "freeze status=$($f.status)"
    $s = Invoke-RestMethod -Method Post -Uri "http://localhost:8080/api/sessions" -ContentType "application/json" -Body "{`"versionId`":$($v.versionId)}"
    Write-Output "sessionId=$($s.sessionId)"
    $st = Invoke-RestMethod -Method Post -Uri "http://localhost:8080/api/sessions/$($s.sessionId)/start"
    Write-Output "start status=$($st.status)"
    try {
        Invoke-RestMethod -Method Post -Uri "http://localhost:8080/api/sessions/$($s.sessionId)/reports" -ContentType "application/json" -Body '{"requestId":"r-2","seq":2,"success":true}' | Out-Null
        Write-Output "skip-seq report unexpectedly succeeded"
    } catch {
        Write-Output "skip-seq report => HTTP $([int]$_.Exception.Response.StatusCode)"
    }
    $r1 = Invoke-RestMethod -Method Post -Uri "http://localhost:8080/api/sessions/$($s.sessionId)/reports" -ContentType "application/json" -Body '{"requestId":"r-1","seq":1,"success":true}'
    Write-Output "report seq1 => $($r1.outcome), lastExecutedSeq=$($r1.lastExecutedSeq)"
    $r1b = Invoke-RestMethod -Method Post -Uri "http://localhost:8080/api/sessions/$($s.sessionId)/reports" -ContentType "application/json" -Body '{"requestId":"r-1","seq":1,"success":true}'
    Write-Output "replay seq1 => $($r1b.outcome)"
    $d = Invoke-RestMethod -Uri "http://localhost:8080/api/sessions/$($s.sessionId)"
    Write-Output "detail cues=$($d.cues.Count), cue1 executed seq=$($d.cues[0].execution.seq)"
}
Stop-Process -Id $proc.Id -Force
Write-Output "stopped"
